window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-13886479edc5d613"]={"versions": [{"id": "FIG-13886479edc5d613", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von <code>ApplicationError</code> im Kontext von Service-Schnittstellen der AUTOSAR Adaptive Platform (Manifest Specification, Metamodell-Ausschnitt für Service Interfaces). Es zeigt die Zuordnung von Fehlern, Methoden und Argumenten auf Metamodellebene unter Berücksichtigung von Variantenbildung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterface</code> (Spezialisierung von <code>PortInterface</code>): Aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>+possibleError</code>: 0..* <code>ApplicationError</code>\n</li><li><code>+method</code>: 0..* <code>ClientServerOperation</code> (stereotypisiert mit «atpVariation»)\n</li></ul>\n</li><li><code>ApplicationError</code> (Spezialisierung von <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ errorCode :Integer</code>\n</li><li>Referenziert über Assoziation <code>+errorContext</code>: 0..* <code>ArgumentDataPrototype</code>\n</li></ul>\n</li><li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Referenziert über Assoziation <code>+possibleError</code>: 0..* <code>ApplicationError</code>\n</li><li>Aggregiert über Komposition <code>+argument</code>: * {ordered} <code>ArgumentDataPrototype</code> (stereotypisiert mit «atpVariation»)\n</li></ul>\n</li><li><code>ArgumentDataPrototype</code> (Spezialisierung von <code>AutosarDataPrototype</code>):\n<ul class=\"fig-list\"><li>Attribute: <code>+ direction :ArgumentDirectionEnum</code>, <code>+ serverArgumentImplPolicy :ServerArgumentImplPolicyEnum [0..1]</code>\n</li></ul>\n</li><li>Annotierte Variation Points («atpVariation»):\n<ul class=\"fig-list\"><li>Für Komposition <code>+method</code>: Tags <code>atp.Status = draft</code>, <code>vh.latestBindingTime = blueprintDerivationTime</code>\n</li><li>Für Komposition <code>+argument</code>: Tag <code>vh.latestBindingTime = blueprintDerivationTime</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein direktes Sequenzdiagramm. Deklariert den Rahmen für synchrone oder asynchrone Methodenaufrufe (<code>ClientServerOperation</code>) innerhalb eines <code>ServiceInterface</code>: Eine Operation kann definierte Fehler (<code>ApplicationError</code>) mit spezifischem Fehlercode (<code>errorCode</code>) zurückgeben, wobei Fehlersituationen über <code>errorContext</code> bestimmten Ein-/Ausgabeargumenten (<code>ArgumentDataPrototype</code>) zugeordnet werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterface</code> definiert den Namensraum und Scope für <code>ApplicationError</code>-Elemente. Eine Operation referenziert spezifisch diejenigen <code>ApplicationError</code>, die sie auslösen kann.\n</li><li>Die Beziehung <code>+method</code> ist als Entwurf markiert (<code>atp.Status = draft</code>) mit Bindungszeitpunkt <code>blueprintDerivationTime</code>.\n</li><li>Die Reihenfolge der Argumente einer Operation ist strikt festgelegt (<code>{ordered}</code>).\n</li><li><code>ArgumentDataPrototype</code> steuert Datenflussrichtung (<code>ArgumentDirectionEnum</code>) und Server-Implementierungsrichtlinie (<code>serverArgumentImplPolicy</code>).\n</li></ul>"}, {"id": "FIG-fe2d17e165a2ed2f", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von <code>ApplicationError</code> im Kontext von Service-Schnittstellen der AUTOSAR Adaptive Platform (Manifest Specification, Metamodell-Ausschnitt für Service Interfaces). Es zeigt die Zuordnung von Fehlern, Methoden und Argumenten auf Metamodellebene unter Berücksichtigung von Variantenbildung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterface</code> (Spezialisierung von <code>PortInterface</code>): Aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>+possibleError</code>: 0..* <code>ApplicationError</code>\n</li><li><code>+method</code>: 0..* <code>ClientServerOperation</code> (stereotypisiert mit «atpVariation»)\n</li></ul>\n</li><li><code>ApplicationError</code> (Spezialisierung von <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ errorCode :Integer</code>\n</li><li>Referenziert über Assoziation <code>+errorContext</code>: 0..* <code>ArgumentDataPrototype</code>\n</li></ul>\n</li><li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ fireAndForget :Boolean [0..1]</code>\n</li><li>Referenziert über Assoziation <code>+possibleError</code>: 0..* <code>ApplicationError</code>\n</li><li>Aggregiert über Komposition <code>+argument</code>: * {ordered} <code>ArgumentDataPrototype</code> (stereotypisiert mit «atpVariation»)\n</li></ul>\n</li><li><code>ArgumentDataPrototype</code> (Spezialisierung von <code>AutosarDataPrototype</code>):\n<ul class=\"fig-list\"><li>Attribute: <code>+ direction :ArgumentDirectionEnum</code>, <code>+ serverArgumentImplPolicy :ServerArgumentImplPolicyEnum [0..1]</code>\n</li></ul>\n</li><li>Annotierte Variation Points («atpVariation»):\n<ul class=\"fig-list\"><li>Für Komposition <code>+method</code>: Tags <code>atp.Status = draft</code>, <code>vh.latestBindingTime = blueprintDerivationTime</code>, <code>mmt.RestrictToStandards = AP</code>\n</li><li>Für Komposition <code>+argument</code>: Tag <code>vh.latestBindingTime = blueprintDerivationTime</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein direktes Sequenzdiagramm. Deklariert den Rahmen für Methodenaufrufe (<code>ClientServerOperation</code>) innerhalb eines <code>ServiceInterface</code>: Eine Operation kann als Fire-and-Forget modelliert werden (<code>fireAndForget = true</code>), wodurch kein Rückgabewert bzw. Fehler zurückgesendet wird, oder als regulärer Aufruf, der definierte Fehler (<code>ApplicationError</code>) mit spezifischem Fehlercode (<code>errorCode</code>) zurückgeben kann. Fehlersituationen können über <code>errorContext</code> bestimmten Parametern (<code>ArgumentDataPrototype</code>) zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterface</code> definiert den Namensraum für <code>ApplicationError</code>-Elemente. Eine Operation verknüpft diejenigen <code>ApplicationError</code>, die bei ihrer Ausführung auftreten können.\n</li><li>Für Methoden im <code>ServiceInterface</code> ist <code>mmt.RestrictToStandards = AP</code> festgelegt; die Methodenkomposition besitzt Draft-Status (<code>atp.Status = draft</code>) mit Bindungszeitpunkt <code>blueprintDerivationTime</code>.\n</li><li>Mit <code>fireAndForget</code> kann spezifiziert werden, ob eine Operation one-way ohne Rückantwort ausgeführt wird.\n</li><li>Die Argumentenliste (<code>+argument</code>) ist geordnet (<code>{ordered}</code>) und unterliegt der Variantenbindung zum Blueprint-Ableitungszeitpunkt.\n</li></ul>"}, {"id": "FIG-1bfbf85c785981b1", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von <code>ApplicationError</code> im Kontext von Service-Schnittstellen der AUTOSAR Adaptive Platform (Manifest Specification, Metamodell-Ausschnitt für Service Interfaces). Es zeigt die Zuordnung von Fehlern, Methoden und Argumenten auf Metamodellebene unter Berücksichtigung von Variantenbildung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterface</code> (Spezialisierung von <code>PortInterface</code>): Aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>+possibleError</code>: 0..* <code>ApplicationError</code>\n</li><li><code>+method</code>: 0..* <code>ClientServerOperation</code> (stereotypisiert mit «atpVariation»)\n</li></ul>\n</li><li><code>ApplicationError</code> (Spezialisierung von <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ errorCode :Integer</code>\n</li><li>Referenziert über Assoziation <code>+errorContext</code>: 0..* <code>ArgumentDataPrototype</code>\n</li></ul>\n</li><li><code>ClientServerOperation</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ fireAndForget :Boolean [0..1]</code>\n</li><li>Referenziert über Assoziation <code>+possibleError</code>: 0..* <code>ApplicationError</code>\n</li><li>Aggregiert über Komposition <code>+argument</code>: * {ordered} <code>ArgumentDataPrototype</code> (stereotypisiert mit «atpVariation»)\n</li></ul>\n</li><li><code>ArgumentDataPrototype</code> (Spezialisierung von <code>AutosarDataPrototype</code>):\n<ul class=\"fig-list\"><li>Attribute: <code>+ direction :ArgumentDirectionEnum</code>, <code>+ serverArgumentImplPolicy :ServerArgumentImplPolicyEnum [0..1]</code>\n</li></ul>\n</li><li>Annotierte Variation Points («atpVariation»):\n<ul class=\"fig-list\"><li>Für Komposition <code>+method</code>: Tags <code>atp.Status = draft</code>, <code>vh.latestBindingTime = blueprintDerivationTime</code>, <code>mmt.RestrictToStandards = AP</code>\n</li><li>Für Komposition <code>+argument</code>: Tag <code>vh.latestBindingTime = blueprintDerivationTime</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein direktes Sequenzdiagramm. Deklariert den Rahmen für Methodenaufrufe (<code>ClientServerOperation</code>) innerhalb eines <code>ServiceInterface</code>: Eine Operation kann als Fire-and-Forget modelliert werden (<code>fireAndForget = true</code>), wodurch kein Rückgabewert bzw. Fehler zurückgesendet wird, oder als regulärer Aufruf, der definierte Fehler (<code>ApplicationError</code>) mit spezifischem Fehlercode (<code>errorCode</code>) zurückgeben kann. Fehlersituationen können über <code>errorContext</code> bestimmten Parametern (<code>ArgumentDataPrototype</code>) zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterface</code> definiert den Namensraum für <code>ApplicationError</code>-Elemente. Eine Operation verknüpft diejenigen <code>ApplicationError</code>, die bei ihrer Ausführung auftreten können.\n</li><li>Für Methoden im <code>ServiceInterface</code> ist <code>mmt.RestrictToStandards = AP</code> festgelegt; die Methodenkomposition besitzt Draft-Status (<code>atp.Status = draft</code>) mit Bindungszeitpunkt <code>blueprintDerivationTime</code>.\n</li><li>Mit <code>fireAndForget</code> kann spezifiziert werden, ob eine Operation one-way ohne Rückantwort ausgeführt wird.\n</li><li>Die Argumentenliste (<code>+argument</code>) ist geordnet (<code>{ordered}</code>) und unterliegt der Variantenbindung zum Blueprint-Ableitungszeitpunkt.\n</li></ul>"}], "trans": [{"from": "FIG-13886479edc5d613", "to": "FIG-fe2d17e165a2ed2f", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ClientServerOperation</code>: Attribut <code>+ fireAndForget :Boolean [0..1]</code> hinzugefügt.\n</li><li><code>ServiceInterface</code> zu <code>ClientServerOperation</code> (Rolle <code>+method</code>): Tag <code>mmt.RestrictToStandards = AP</code> am Stereotyp «atpVariation» ergänzt.\n</li></ul>"}, {"from": "FIG-fe2d17e165a2ed2f", "to": "FIG-1bfbf85c785981b1", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
